const config = $input.first().json;
function checkedBase(value) {
  if (typeof value !== 'string' || /[\s\\]/.test(value)) throw new Error('Configure a plain trusted base URL.');
  const match = /^(https?):\/\/([^\/?#]+)(\/[^?#]*)?$/.exec(value);
  if (!match || !/^(\[[0-9a-fA-F:]+\]|[a-zA-Z0-9.-]+)(:\d{1,5})?$/.test(match[2])) throw new Error('URL credentials, queries, fragments and invalid hosts are not permitted.');
  if (match[1] !== 'https' && !/^(localhost|127\.0\.0\.1|host\.docker\.internal)(:\d{1,5})?$/i.test(match[2])) throw new Error('Remote endpoints require HTTPS before sending credentials.');
  return value.replace(/\/$/, '');
}

const supabaseBaseUrl = checkedBase(config.supabaseBaseUrl);
if (!/^https?:\/\/[^/]+$/.test(supabaseBaseUrl)) throw new Error('Supabase must be a project origin.');
if (!/^[a-z][a-z0-9_]{0,30}$/.test(config.alias) || !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(config.rowId)) throw new Error('Configure a registered alias and UUID row ID.');
const patch = JSON.parse(config.patch);
if (!patch || Array.isArray(patch) || typeof patch !== 'object' || !Object.keys(patch).length || Object.keys(patch).length>20 || Object.entries(patch).some(([k,v])=>!k || !['string','number','boolean'].includes(typeof v) || (typeof v==='number'&&!Number.isFinite(v)) || String(v).length>2000)) throw new Error('Configure 1–20 supported non-null scalar fields.');
const connection=config.connection||'default';
if(typeof connection!=='string'||!/^[a-z][a-z0-9_-]{0,62}$/.test(connection)) throw new Error('Configure a connection name matching the recorded operation.');
return [{json:{connection,rewindBaseUrl:checkedBase(config.rewindBaseUrl),supabaseBaseUrl,alias:config.alias,rowId:config.rowId,patch}}];

const response=$input.first().json;
if (response.statusCode!==200 || !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(response.body?.version)) throw new Error('No valid row revision returned. No update attempted.');
return [{json:{version:response.body.version}}];

const response=$input.first().json, result=response.body, config=$('Validate endpoints').first().json;
if (response.statusCode!==200 || !result || !/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(result.version) || result.version===$('Validate read').first().json.version || !result.before || !result.after) throw new Error('Update response could not be verified. Inspect the row; do not repeat the write.');
return [{json:{rewindBaseUrl:config.rewindBaseUrl,connection:config.connection,beforeVersion:'"'+$('Validate read').first().json.version+'"',idempotencyKey:'supabase-'+$execution.id+'-'+config.alias+'-'+config.rowId,title:'Update '+config.alias,resource:config.alias+':'+config.rowId,kind:'supabase_row',before:result.before,after:result.after,afterVersion:'"'+result.version+'"'}}];

function checkedBase(value) {
  if (typeof value !== 'string' || /[\s\\]/.test(value)) throw new Error('Configure a plain trusted base URL.');
  const match = /^(https?):\/\/([^\/?#]+)(\/[^?#]*)?$/.exec(value);
  if (!match || !/^(\[[0-9a-fA-F:]+\]|[a-zA-Z0-9.-]+)(:\d{1,5})?$/.test(match[2])) throw new Error('URL credentials, queries, fragments and invalid hosts are not permitted.');
  if (match[1] !== 'https' && !/^(localhost|127\.0\.0\.1|host\.docker\.internal)(:\d{1,5})?$/i.test(match[2])) throw new Error('Remote endpoints require HTTPS before sending credentials.');
  return value.replace(/\/$/, '');
}

return $input.all().map((item,index) => {
  const data=item.json;
  const rewindBaseUrl=checkedBase(data.rewindBaseUrl);
  const problem=message=>{throw new Error('Input '+(index+1)+': '+message);};
  if (!/^[A-Za-z0-9_-]{8,100}$/.test(data.idempotencyKey||'')) problem('Supply a stable idempotencyKey for this action.');
  if (typeof data.title!=='string'||!data.title.trim()||data.title.length>100) problem('Supply a title up to 100 characters.');
  if (typeof data.resource!=='string'||!data.resource.trim()||data.resource.length>200) problem('Supply a resource reference.');
  if (!['conditional_http','supabase_row','irreversible'].includes(data.kind)) problem('Choose conditional_http, supabase_row or irreversible.');
  if (data.kind==='conditional_http' && !/^[A-Za-z0-9_-]{1,160}$/.test(data.resource)) problem('Use a simple resource ID, not a URL.');
  if(data.kind==='supabase_row' && (!/^[a-z][a-z0-9_]{0,30}:[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(data.resource)||!/^"[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"$/.test(data.afterVersion||''))) problem('Use alias:uuid and a quoted UUID revision for Supabase rows.');
  for(const name of ['before','after']){
    const value=data[name];
    if(!value||typeof value!=='object'||Array.isArray(value)) problem('Pass captured before and after objects from your successful action.');
    const entries=Object.entries(value);
    if(!entries.length||entries.length>20) problem('Record 1–20 top-level fields.');
    for(const [key,v] of entries){
      if(!/^[a-zA-Z][a-zA-Z0-9_-]{0,63}$/.test(key)||['__proto__','constructor','prototype'].includes(key)) problem('Unsupported field name.');
      if(!(v===null||typeof v==='boolean'||(typeof v==='number'&&Number.isFinite(v))||(typeof v==='string'&&v.length<=2000))) problem('Only scalar snapshots are supported.');
      if(data.kind!=='irreversible'&&v===null) problem('Conditional recovery supports existing non-null fields only.');
    }
  }
  if(Object.keys(data.before).sort().join(',')!==Object.keys(data.after).sort().join(',')) problem('Before and after must cover the same fields.');
  if(data.kind!=='irreversible' && !(typeof data.afterVersion==='string'&&/^"[\x21\x23-\x7e]{1,180}"$/.test(data.afterVersion))) problem('Use the strong ETag returned by your successful write.');
  const payload={idempotencyKey:data.idempotencyKey,title:data.title,resource:data.resource,kind:data.kind,before:data.before,after:data.after};
  if(data.kind!=='irreversible') payload.afterVersion=data.afterVersion;
  const connection=data.connection??data.defaultConnection??'default';
  if(typeof connection!=='string'||!/^[a-z][a-z0-9_-]{0,62}$/.test(connection)) problem('Use a valid connection name matching your recovery worker.');
  if(connection!=='default')payload.connection=connection;
  if(data.beforeVersion!==undefined){
    if(typeof data.beforeVersion!=='string'||!/^"[\x21\x23-\x7e]{1,180}"$/.test(data.beforeVersion)) problem('beforeVersion must be the strong version read before the write.');
    payload.beforeVersion=data.beforeVersion;
  }
  if(data.run!==undefined){
    const r=data.run;
    if(!r||typeof r!=='object'||Array.isArray(r)||typeof r.id!=='string'||!/^[A-Za-z0-9_-]{8,100}$/.test(r.id)||typeof r.name!=='string'||!r.name.trim()||r.name.length>100||!Number.isSafeInteger(r.step)||r.step<1||r.step>100) problem('Supply a stable run id, name and consecutive step from 1 to 100.');
    payload.run={id:r.id,name:r.name.trim(),step:r.step};
  }
  return {json:{rewindBaseUrl,payload},pairedItem:{item:index}};
});
